// Validates a converted Boris-2 GGUF against logits of the PyTorch reference model.
//
//   test_boris2_logits --gguf FILE --ref FILE --precision f32|f16 [--mode refuse-eos]
//
// The reference file (native/tests/refgen/formats.py) holds token sequences made of a ChatML
// prompt rendered as plain text and the reference's greedy reply, with the reference's logits.
// The reference has no cache: every one of its replies was generated by recomputing the whole
// prefix for each token, which is what the port's incremental decoding must reproduce.
//
// --precision f32 is the gate for the port itself: F32 file, F32 KV cache, no flash attention.
// Every way of feeding the same tokens must reproduce the reference logits within 5e-3 and the
// greedy reply exactly.
//
// --precision f16 is the gate for the file that ships (F16 KV cache, default attention path):
// the distributions must stay within the KL and top-1 limits of the 16-bit format. It needs a
// reference with the whole logit vector at every position.
//
// Both precisions run the memory checks that are specific to this architecture. Its Canon
// layers keep two columns of history per layer in a recurrent row that cannot be rewound, so
// - llama_memory_seq_rm() into the sequence must report failure and change nothing;
// - a checkpoint of that row (LLAMA_STATE_SEQ_FLAGS_PARTIAL_ONLY) restored before the removal
//   must make the rewind exact;
// - a rewind with the wrong row must be visibly wrong, or the two checks above prove nothing;
// - a full state save and restore must carry the row and the token history of the n-gram input.
//
// --mode refuse-eos is a second, short run. One sequence is one document for this port, which is
// exact only while the end-of-text token is never fed; the graph asserts that. An assertion
// ends the process, so this mode feeds the token and passes when the assertion fires.

#include "support/logit_support.h"

#include "gguf.h"

#include <cstring>

namespace {

using namespace pp_test;

using blob = std::vector<uint8_t>;

// The state of a sequence that llama_memory_seq_rm() cannot rewind: for this architecture the
// Canon rows, and no KV cells. This is the checkpoint an application takes at message boundaries.
blob checkpoint(llama_context * ctx, llama_seq_id seq = 0) {
    blob data(llama_state_seq_get_size_ext(ctx, seq, LLAMA_STATE_SEQ_FLAGS_PARTIAL_ONLY));
    if (llama_state_seq_get_data_ext(ctx, data.data(), data.size(), seq, LLAMA_STATE_SEQ_FLAGS_PARTIAL_ONLY) != data.size()) {
        die("cannot take a checkpoint");
    }
    return data;
}

bool restore(llama_context * ctx, const blob & data, llama_seq_id seq = 0) {
    return llama_state_seq_set_data_ext(ctx, data.data(), data.size(), seq, LLAMA_STATE_SEQ_FLAGS_PARTIAL_ONLY) == data.size();
}

// llama_process logs an error when it refuses a batch; where the refusal is the expected
// outcome the log would only look like a failure.
int32_t process_silently(evaluator & ev, const std::vector<llama_token> & ids, size_t begin, size_t end) {
    llama_log_set([](enum ggml_log_level, const char *, void *) {}, nullptr);
    const int32_t rc = ev.process(ids, begin, end);
    quiet_logs();
    return rc;
}

// Two runs of the port that must agree: within the F32 limit over the whole vocabulary, or,
// with an F16 cache (whose cells were rounded from values computed in another batch shape),
// within the limits of the 16-bit format.
void same(report & r, bool f16, const logit_limits & limits, const char * what, double max_abs, const agreement & a) {
    if (f16) {
        judge(r, true, what, a, limits);
    } else {
        r.check(max_abs <= limits.f32_max_abs, "%-34s max |dlogit| %.3g (limit %.0e), whole vocabulary", what, max_abs, limits.f32_max_abs);
    }
}

// ggml calls this with the text of a failed assertion and aborts when it returns. In the
// refuse-eos mode the assertion about the end-of-text token is the expected outcome.
void expect_eos_refusal(const char * message) {
    const bool expected = std::strstr(message, "the end-of-text token cannot be an input") != nullptr;
    std::printf("%s  feeding the end-of-text token stops the process: %s\n", expected ? "ok  " : "FAIL", message);
    std::printf("%s: 1 check(s), %d failed\n", expected ? "PASSED" : "FAILED", expected ? 0 : 1);
    std::fflush(stdout);
    std::_Exit(expected ? 0 : 1);
}

// The sorted bigram keys of the file's n-gram lookup; empty when the file has none.
std::vector<uint64_t> read_bigram_keys(const std::string & path) {
    std::vector<uint64_t> keys;
    gguf_init_params params = {true, nullptr};
    gguf_context * ctx = gguf_init_from_file(path.c_str(), params);
    if (ctx == nullptr) {
        die("cannot read the metadata of " + path);
    }
    const int64_t kid = gguf_find_key(ctx, "boris2.ngram.bigram_keys");
    if (kid >= 0 && gguf_get_kv_type(ctx, kid) == GGUF_TYPE_ARRAY && gguf_get_arr_type(ctx, kid) == GGUF_TYPE_UINT64) {
        const uint64_t * data = (const uint64_t *) gguf_get_arr_data(ctx, kid);
        keys.assign(data, data + gguf_get_arr_n(ctx, kid));
    }
    gguf_free(ctx);
    return keys;
}

} // namespace

int main(int argc, char ** argv) {
    std::string gguf, ref_path, precision, mode;
    for (int i = 1; i + 1 < argc; i += 2) {
        const std::string key = argv[i];
        if (key == "--gguf") {
            gguf = argv[i + 1];
        } else if (key == "--ref") {
            ref_path = argv[i + 1];
        } else if (key == "--precision") {
            precision = argv[i + 1];
        } else if (key == "--mode") {
            mode = argv[i + 1];
        }
    }
    if (gguf.empty() || ref_path.empty() || (precision != "f32" && precision != "f16") || (!mode.empty() && mode != "refuse-eos")) {
        std::fprintf(stderr, "usage: %s --gguf FILE --ref FILE --precision f32|f16 [--mode refuse-eos]\n", argv[0]);
        return 2;
    }
    const bool f16 = precision == "f16";

    // The design's limits for this model: the F16 mean KL is five times the peacebell one,
    // because the F16 KV cache meets a wider logit range here.
    logit_limits limits;
    limits.f16_mean_kl = 5e-5;

    quiet_logs();
    llama_backend_init();
    report r;
    {
        const reference ref = load_reference(ref_path);
        model_ptr model = load_model(gguf, false);
        const llama_vocab * vocab = llama_model_get_vocab(model.get());
        const uint64_t n_vocab = (uint64_t) llama_vocab_n_tokens(vocab);
        if (n_vocab != ref.n_vocab) {
            die("the reference was made for a vocabulary of another size");
        }
        if (f16 && !ref.full_everywhere()) {
            die("--precision f16 needs a reference with the whole logit vector at every position");
        }
        const std::string arch = meta(model.get(), "general.architecture");
        r.check(arch == "boris2", "architecture is '%s'", arch.c_str());
        r.note("%s, %s weights, %s KV cache, %d thread(s), %zu sequences", gguf.substr(gguf.find_last_of('/') + 1).c_str(),
               precision.c_str(), f16 ? "F16" : "F32", n_threads(), ref.seqs.size());

        // One conversation is one document: the port is exact only while the end-of-text token is
        // never fed, and the graph refuses it. The reference sequences must respect that too.
        const llama_token eos = llama_vocab_eos(vocab);
        bool eos_fed = false;
        for (const sequence & s : ref.seqs) {
            eos_fed = eos_fed || std::find(s.ids.begin(), s.ids.end(), eos) != s.ids.end();
        }
        r.check(eos == 0 && llama_vocab_is_eog(vocab, eos) && !eos_fed, "end-of-text token %d ends a generation and occurs in no reference sequence", eos);

        evaluator ev(model.get(), f16);
        const std::vector<size_t> one_batch = {k_n_batch};
        const std::vector<size_t> one_token = {1};

        if (mode == "refuse-eos") {
            // A prompt as usual, then the token that would start a new document in the reference.
            std::vector<llama_token> ids(ref.seqs[0].ids.begin(), ref.seqs[0].ids.begin() + ref.seqs[0].n_prompt);
            ev.open(k_n_batch);
            ev.decode(ids, 0, ids.size(), one_batch);
            ids.push_back(eos);
            ggml_set_abort_callback(expect_eos_refusal);
            const int32_t rc = ev.process(ids, ids.size() - 1, ids.size());
            ggml_set_abort_callback(nullptr);
            r.check(false, "the end-of-text token was accepted as input (llama_process returned %d)", rc);
            return r.finish();
        }
        // Uneven on purpose: single tokens between larger batches, as a chat produces them. The
        // Canon history then crosses a batch boundary at every offset.
        const std::vector<size_t> mixed = {3, 1, 1, 8, 2, 1, 17, k_n_batch};

        // One batch, token by token and uneven batches against the reference; and against each
        // other, which catches a memory or position error even where the reference is sparse.
        ev.open(k_n_batch);
        std::vector<logit_rows> baseline;
        agreement a_batch, a_token, a_mixed;
        double d_token = 0.0, d_mixed = 0.0;
        for (const sequence & s : ref.seqs) {
            const size_t n = s.ids.size();
            ev.clear();
            baseline.push_back(ev.decode(s.ids, 0, n, one_batch));
            compare(ref, s, baseline.back(), 0, n, limits, a_batch);

            ev.clear();
            const logit_rows by_token = ev.decode(s.ids, 0, n, one_token);
            compare(ref, s, by_token, 0, n, limits, a_token);
            d_token = std::max(d_token, max_abs_between(baseline.back(), by_token, 0, n));

            ev.clear();
            const logit_rows by_mixed = ev.decode(s.ids, 0, n, mixed);
            compare(ref, s, by_mixed, 0, n, limits, a_mixed);
            d_mixed = std::max(d_mixed, max_abs_between(baseline.back(), by_mixed, 0, n));
        }
        judge(r, f16, "one batch vs reference:", a_batch, limits);
        judge(r, f16, "token by token vs reference:", a_token, limits);
        judge(r, f16, "uneven batches vs reference:", a_mixed, limits);
        if (!f16) {
            r.check(d_token <= limits.f32_max_abs, "token by token vs one batch:        max |dlogit| %.3g (limit %.0e), whole vocabulary", d_token, limits.f32_max_abs);
            r.check(d_mixed <= limits.f32_max_abs, "uneven batches vs one batch:        max |dlogit| %.3g (limit %.0e), whole vocabulary", d_mixed, limits.f32_max_abs);
        }

        // The checkpoint an application keeps per message boundary, and its size.
        {
            const sequence & s = ref.seqs[0];
            ev.clear();
            ev.decode(s.ids, 0, s.n_prompt, one_batch);
            const size_t n_bytes = checkpoint(ev.context()).size();
            const size_t n_layer = (size_t) std::atoi(meta(model.get(), arch + ".block_count").c_str());
            const size_t n_embd = (size_t) std::atoi(meta(model.get(), arch + ".embedding_length").c_str());
            // Two saved columns of the fused Q|K|V projection (3 * n_embd wide) per layer, float32.
            const size_t n_rows = n_layer * 2 * 3 * n_embd * sizeof(float);
            r.check(n_bytes >= n_rows && n_bytes < n_rows + 4096,
                    "a checkpoint is %zu bytes: %zu bytes of Canon history (%zu layers x 2 columns x %zu float32) and %zu of framing",
                    n_bytes, n_rows, n_layer, 3 * n_embd, n_bytes - n_rows);
        }

        // Without a checkpoint the memory must refuse to be cut inside the sequence, and say so.
        {
            const sequence & s = ref.seqs[0];
            const size_t n = s.ids.size();
            llama_memory_t mem = llama_get_memory(ev.context());
            ev.clear();
            ev.decode(s.ids, 0, n - 1, one_batch);
            const size_t cuts[] = {1, s.n_prompt, n - 2};
            size_t n_refused = 0;
            for (const size_t cut : cuts) {
                n_refused += ev.rewind(cut) ? 0 : 1;
            }
            r.check(n_refused == std::size(cuts) && llama_memory_seq_pos_max(mem, 0) == (llama_pos) n - 2,
                    "llama_memory_seq_rm refused %zu of %zu cuts inside the sequence (at %zu, %zu, %zu of %zu) and removed nothing",
                    n_refused, std::size(cuts), cuts[0], cuts[1], cuts[2], n - 1);

            // A caller that ignores the refusal and decodes at the cut is stopped by the position check.
            const int32_t rc = process_silently(ev, s.ids, s.n_prompt, s.n_prompt + 1);
            r.check(rc != 0, "decoding at the refused cut is rejected (llama_process returned %d)", rc);

            // Nothing was damaged by the refusals: the next token continues as if they had not happened.
            const logit_rows last = ev.decode(s.ids, n - 1, n, one_token);
            agreement a_intact;
            compare_rows(baseline[0], last, n - 1, n, limits, a_intact);
            same(r, f16, limits, "after the refusals, next token:", max_abs_between(baseline[0], last, n - 1, n), a_intact);

            // Cutting at the end removes nothing and removing the whole sequence is always possible.
            const bool at_end = ev.rewind(n);
            const bool whole = llama_memory_seq_rm(mem, 0, -1, -1);
            r.check(at_end && whole && llama_memory_seq_pos_max(mem, 0) == -1, "a cut at the end and the removal of the whole sequence succeed");
        }

        // Rewind through a checkpoint, against the reference: decode one conversation with a
        // checkpoint where it stops sharing its beginning with another one, then restore the
        // checkpoint, cut the memory there and decode the other one's tail.
        {
            agreement a_rewind;
            size_t n_rewinds = 0;
            bool all_ok = true;
            for (size_t i = 0; i < ref.seqs.size(); i++) {
                const sequence & from = ref.seqs[i];
                const sequence & to = ref.seqs[(i + 1) % ref.seqs.size()];
                const size_t keep = common_prefix(from.ids, to.ids);
                if (keep == 0 || keep == to.ids.size() || keep == from.ids.size()) {
                    continue;
                }
                ev.clear();
                ev.decode(from.ids, 0, keep, one_batch);
                const blob saved = checkpoint(ev.context());
                ev.decode(from.ids, keep, from.ids.size(), one_batch);
                all_ok = restore(ev.context(), saved) && ev.rewind(keep) && all_ok;
                const logit_rows tail = ev.decode(to.ids, keep, to.ids.size(), one_batch);
                compare(ref, to, tail, keep, to.ids.size(), limits, a_rewind);
                n_rewinds++;
            }
            r.check(all_ok && n_rewinds > 0, "checkpoint restore and llama_memory_seq_rm succeeded for %zu rewind(s) to a shared prefix", n_rewinds);
            judge(r, f16, "after a rewind vs reference:", a_rewind, limits);
        }

        // Rewind at arbitrary positions: a checkpoint at or shortly before the cut, the old
        // tail, then restore, cut at the checkpoint, decode again from the checkpoint to the cut
        // and continue with a different tail. That must equal a fresh evaluation of the spliced
        // sequence. The positions come from a fixed generator.
        struct splice {
            size_t head, cut;
            std::vector<llama_token> ids;
            logit_rows fresh;
        };
        std::vector<splice> splices;
        {
            double d_splice = 0.0;
            agreement a_splice;
            double d_control = std::numeric_limits<double>::infinity();
            bool all_ok = true;
            size_t n_redecoded = 0;
            uint32_t state = 12345;
            const auto next = [&](uint32_t bound) {
                state = state * 1664525u + 1013904223u;
                return (state >> 8) % bound;
            };
            const int n_cuts = 20;
            for (int c = 0; c < n_cuts; c++) {
                const size_t i_head = next((uint32_t) ref.seqs.size());
                const sequence & head = ref.seqs[i_head];
                const sequence & tail = ref.seqs[next((uint32_t) ref.seqs.size())];
                const size_t limit = std::min(head.ids.size(), tail.ids.size()) - 1;
                const size_t cut = 1 + next((uint32_t) (limit - 1));
                // The checkpoint an application has is at a message boundary, usually before the cut.
                const size_t saved_at = cut - std::min<size_t>(cut - 1, next(4));
                std::vector<llama_token> spliced(head.ids.begin(), head.ids.begin() + (long) cut);
                spliced.insert(spliced.end(), tail.ids.begin() + (long) cut, tail.ids.end());

                ev.clear();
                ev.decode(head.ids, 0, saved_at, one_batch);
                const blob saved = checkpoint(ev.context());
                ev.decode(head.ids, saved_at, head.ids.size(), one_batch);
                all_ok = restore(ev.context(), saved) && ev.rewind(saved_at) && all_ok;
                ev.decode(spliced, saved_at, cut, one_batch);
                n_redecoded += cut - saved_at;
                const logit_rows after_cut = ev.decode(spliced, cut, spliced.size(), one_batch);

                ev.clear();
                logit_rows fresh = ev.decode(spliced, 0, spliced.size(), one_batch);
                d_splice = std::max(d_splice, max_abs_between(after_cut, fresh, cut, spliced.size()));
                compare_rows(fresh, after_cut, cut, spliced.size(), limits, a_splice);

                // The control: the same tail after the wrong beginning. If this did not move the
                // logits, the comparison above would prove nothing about what the memory holds.
                if (!std::equal(head.ids.begin(), head.ids.begin() + (long) cut, tail.ids.begin())) {
                    ev.clear();
                    ev.decode(tail.ids, 0, cut, one_batch);
                    const logit_rows wrong = ev.decode(spliced, cut, spliced.size(), one_batch);
                    d_control = std::min(d_control, max_abs_between(wrong, fresh, cut, spliced.size()));
                }
                if (splices.size() < 4 && cut + 2 < head.ids.size()) {
                    splices.push_back({i_head, cut, std::move(spliced), std::move(fresh)});
                }
            }
            r.check(all_ok, "checkpoint restore and llama_memory_seq_rm succeeded for %d rewinds at arbitrary positions (%zu tokens decoded again)",
                    n_cuts, n_redecoded);
            same(r, f16, limits, "arbitrary rewinds vs fresh run:", d_splice, a_splice);
            r.check(d_control >= 0.5 && std::isfinite(d_control),
                    "control, the wrong beginning:       max |dlogit| at least %.3g in every case (must exceed 0.5)", d_control);
        }

        // Full state save and restore into a new context: the KV cells with their token ids
        // (the n-gram input reads its history from them) and the Canon rows. The next tokens
        // must come out bit for bit as they do without the round trip. The split is placed where
        // the first token after it has a bigram in the table, so that a restore which lost the
        // token history would give that token another table row and fail the comparison.
        {
            const std::vector<uint64_t> bigrams = read_bigram_keys(gguf);
            const sequence * chosen = &ref.seqs[0];
            size_t split = chosen->n_prompt;
            bool has_hit = false;
            for (const sequence & s : ref.seqs) {
                for (size_t m = s.n_prompt; !has_hit && m + 4 <= s.ids.size(); m++) {
                    const uint64_t key = (uint64_t) s.ids[m - 1] * n_vocab + (uint64_t) s.ids[m];
                    if (std::binary_search(bigrams.begin(), bigrams.end(), key)) {
                        chosen = &s;
                        split = m;
                        has_hit = true;
                    }
                }
            }
            const sequence & s = *chosen;
            const size_t n_next = std::min<size_t>(4, s.ids.size() - split);

            ev.open(k_n_batch);
            ev.decode(s.ids, 0, split, one_batch);
            blob state(llama_state_seq_get_size(ev.context(), 0));
            const size_t n_state = llama_state_seq_get_data(ev.context(), state.data(), state.size(), 0);
            const logit_rows before = ev.decode(s.ids, split, split + n_next, one_token);

            ev.open(k_n_batch);
            const size_t n_read = llama_state_seq_set_data(ev.context(), state.data(), n_state, 0);
            const logit_rows after = ev.decode(s.ids, split, split + n_next, one_token);
            const bool identical = before.data.size() == after.data.size()
                    && std::memcmp(before.data.data(), after.data.data(), before.data.size() * sizeof(float)) == 0;
            r.check(n_state > 0 && n_read == n_state && identical,
                    "full state round trip into a new context: %zu bytes for %zu tokens, the next %zu tokens bit-identical",
                    n_state, split, n_next);
            if (bigrams.empty()) {
                r.note("the file has no n-gram lookup: the round trip does not depend on the token history");
            } else {
                r.check(has_hit, "the first token after the restore (position %zu) has a bigram in the table: its row depends on the restored token history", split);
            }
        }

        // Greedy generation as the app runs it: the prompt in one batch, then one token per call.
        // The reference recomputed the whole prefix for every one of these tokens.
        {
            size_t n_same = 0, n_prompt_tokens = 0, n_reply_tokens = 0;
            double seconds_prompt = 0.0, seconds_reply = 0.0;
            std::string first_divergence = "none";
            llama_sampler * sampler = llama_sampler_chain_init(llama_sampler_chain_default_params());
            llama_sampler_chain_add(sampler, llama_sampler_init_greedy());
            ev.open(k_n_batch);
            for (size_t k = 0; k < ref.seqs.size(); k++) {
                const sequence & s = ref.seqs[k];
                std::vector<llama_token> ids(s.ids.begin(), s.ids.begin() + s.n_prompt);
                ev.clear();
                int64_t t0 = llama_time_us();
                if (ev.process(ids, 0, ids.size()) != 0) {
                    die("cannot decode a prompt");
                }
                seconds_prompt += (double) (llama_time_us() - t0) / 1e6;
                // The reference reply is cut where its text first contains the end marker or at
                // the reference's length limit; the port is given the same number of tokens.
                std::vector<llama_token> reply;
                while (reply.size() < s.greedy.size()) {
                    const llama_token token = llama_sampler_sample(sampler, ev.context(), -1);
                    if (llama_vocab_is_eog(vocab, token)) {
                        break;
                    }
                    reply.push_back(token);
                    ids.push_back(token);
                    if (reply.size() == s.greedy.size()) {
                        break;
                    }
                    t0 = llama_time_us();
                    if (ev.process(ids, ids.size() - 1, ids.size()) != 0) {
                        die("cannot decode a generated token");
                    }
                    seconds_reply += (double) (llama_time_us() - t0) / 1e6;
                    n_reply_tokens++;
                }
                if (reply == s.greedy) {
                    n_same++;
                } else if (first_divergence == "none") {
                    first_divergence = "sequence " + std::to_string(k) + ", reply token " + std::to_string(common_prefix(reply, s.greedy));
                }
                n_prompt_tokens += s.n_prompt;
            }
            llama_sampler_free(sampler);
            if (f16) {
                // Reported, not gated: the 16-bit limits are statistical (top-1 above), and one
                // near-tie flipping would be within them.
                r.note("greedy replies identical to the reference: %zu of %zu, first divergence: %s", n_same, ref.seqs.size(), first_divergence.c_str());
            } else {
                r.check(n_same == ref.seqs.size(), "greedy replies identical to the reference's full-prefix recomputation: %zu of %zu, first divergence: %s",
                        n_same, ref.seqs.size(), first_divergence.c_str());
            }
            r.note("speed: prompt %.0f tokens/s (%zu tokens in one batch each), generation %.1f tokens/s (%zu tokens)",
                   (double) n_prompt_tokens / seconds_prompt, n_prompt_tokens, (double) n_reply_tokens / seconds_reply, n_reply_tokens);
        }

        // Every micro-batch size must give the same logits: the cache, the positions, the Canon
        // history and the token history are then right however llama.cpp cuts a batch internally.
        {
            double d_ubatch = 0.0;
            agreement a_ubatch;
            const uint32_t sizes[] = {1, 2, 7, 32, 512};
            for (const uint32_t n_ubatch : sizes) {
                ev.open(n_ubatch);
                for (size_t k = 0; k < ref.seqs.size(); k++) {
                    const sequence & s = ref.seqs[k];
                    ev.clear();
                    const logit_rows rows = ev.decode(s.ids, 0, s.ids.size(), one_batch);
                    compare(ref, s, rows, 0, s.ids.size(), limits, a_ubatch);
                    d_ubatch = std::max(d_ubatch, max_abs_between(baseline[k], rows, 0, s.ids.size()));
                }
            }
            judge(r, f16, "n_ubatch 1, 2, 7, 32, 512 vs ref.:", a_ubatch, limits);
            if (!f16) {
                r.check(d_ubatch <= limits.f32_max_abs, "n_ubatch 1, 2, 7, 32, 512 vs default:   max |dlogit| %.3g (limit %.0e), whole vocabulary", d_ubatch, limits.f32_max_abs);
            }
        }

        // The negative control of the checkpoint discipline: the KV cache cut back to the kept
        // tokens while the Canon rows are still those of the old tail, which is what a rewind
        // that skipped the restore would leave if the memory allowed it. The API never produces
        // that state for one sequence, so it is built from two: sequence 1 holds only the kept
        // tokens, and receives the Canon rows of sequence 0, which went on to the old end.
        // (A partial-only state carries no KV cells.) The new tail must then come out wrong.
        if (!splices.empty()) {
            double d_stale = std::numeric_limits<double>::infinity();
            ev.open(k_n_batch, 2);
            for (const splice & sp : splices) {
                const sequence & head = ref.seqs[sp.head];
                ev.clear();
                ev.decode(head.ids, 0, head.ids.size(), one_batch, 0);
                ev.decode(head.ids, 0, sp.cut, one_batch, 1);
                if (!restore(ev.context(), checkpoint(ev.context(), 0), 1)) {
                    die("cannot move a partial state between sequences");
                }
                const logit_rows stale = ev.decode(sp.ids, sp.cut, sp.ids.size(), one_batch, 1);
                d_stale = std::min(d_stale, max_abs_between(stale, sp.fresh, sp.cut, sp.ids.size()));
            }
            r.check(d_stale >= 0.5 && std::isfinite(d_stale),
                    "control, a rewind with stale Canon history: max |dlogit| at least %.3g in each of %zu cases (must exceed 0.5)", d_stale, splices.size());
        } else {
            r.check(false, "no sequence pair to build the stale-history control from");
        }

        // Two sequences in one batch, their tokens interleaved and their lengths different. The
        // app uses one sequence; this pins what the graph assumes about a ubatch that holds
        // several (equal token counts, sequence after sequence), which the Canon state and the
        // n-gram history both depend on.
        {
            const sequence & a = ref.seqs[0];
            const sequence & b = ref.seqs[1 % ref.seqs.size()];
            const size_t n_a = a.ids.size(), n_b = b.ids.size();
            if (n_a + n_b > k_n_batch) {
                die("the first two reference sequences do not fit one batch");
            }
            ev.open(k_n_batch, 2);
            llama_batch_ext * batch = llama_batch_ext_init(ev.context());
            std::vector<int32_t> index_a, index_b;
            for (size_t t = 0; t < std::max(n_a, n_b); t++) {
                const llama_pos pos = (llama_pos) t;
                for (int seq = 0; seq < 2; seq++) {
                    const sequence & s = seq == 0 ? a : b;
                    if (t >= s.ids.size()) {
                        continue;
                    }
                    const int32_t idx = llama_batch_ext_add_token(batch, seq, s.ids[t]);
                    if (idx < 0 || !llama_batch_ext_set_pos(batch, idx, &pos) || !llama_batch_ext_set_output_logits(batch, idx, true)) {
                        die("cannot build a batch");
                    }
                    (seq == 0 ? index_a : index_b).push_back(idx);
                }
            }
            if (llama_process(ev.context(), LLAMA_PROCESS_TYPE_DECODE, batch) != 0) {
                die("cannot decode two sequences in one batch");
            }
            const auto rows_of = [&](const std::vector<int32_t> & index) {
                logit_rows rows;
                rows.n_vocab = (size_t) n_vocab;
                for (const int32_t idx : index) {
                    const float * logits = llama_get_logits_ith(ev.context(), idx);
                    rows.data.insert(rows.data.end(), logits, logits + n_vocab);
                }
                return rows;
            };
            const logit_rows rows_a = rows_of(index_a), rows_b = rows_of(index_b);
            llama_batch_ext_free(batch);
            agreement a_both;
            compare_rows(baseline[0], rows_a, 0, n_a, limits, a_both);
            compare_rows(baseline[1 % ref.seqs.size()], rows_b, 0, n_b, limits, a_both);
            same(r, f16, limits, "two sequences in one batch vs alone:",
                 std::max(max_abs_between(baseline[0], rows_a, 0, n_a), max_abs_between(baseline[1 % ref.seqs.size()], rows_b, 0, n_b)), a_both);
        }
    }
    llama_backend_free();
    return r.finish();
}
